import re,base64,os,sys,binascii
pat=re.compile(rb'[A-Za-z0-9+/_-]{12,}={0,2}')
n=0
for root,_,fs in os.walk(sys.argv[1]):
  for f in fs:
    p=os.path.join(root,f); data=open(p,'rb').read()
    for m in pat.finditer(data):
      s=m.group()
      for dec in (base64.b64decode, base64.urlsafe_b64decode):
        try:
          t=s+b'='*(-len(s)%4); d=dec(t)
        except Exception: continue
        try: d=d.decode('ascii')
        except: continue
        if all(32<=ord(c)<127 for c in d) and ':' in d and len(d)>=4:
          ln=data[:m.start()].count(b'\n')+1; print('B64',p,ln,repr(d[:3]+'...')); n+=1
        break
print('candidates',n)
EOF
echo "== json auth fields"; grep -rniE '"(authentication|username|password|httpClient|bearerToken|ntlm|preemptive|userId|emailAddress|firstName|lastName|source)"' docs/measurements | cut -c1-200 | head -30

